mapper.select:
select DISTINCT v.VENDOR_ID, v.VENDOR_CODE, v.VENDOR_NAME, i.ORG_OU_ID, i.ORG_OU_CODE, i.ORG_OU_NAME from scc_sou_vendor v
join scc_sou_project p on p.PROJECT_ID = v.PROJECT_ID and p.SOU_TYPE='inq' and p.CREATE_APPROVAL_STATUS='APPROVED'
join scc_sou_item i on i.PROJECT_ID = p.PROJECT_ID

    and p.CREATION_DATE >= #{creationDateFrom}
    and p.CREATION_DATE < #{creationDateTo}
    and v.VENDOR_CODE like CONCAT('%', #{vendorCode},'%')
    and v.VENDOR_NAME like CONCAT('%', #{vendorName},'%')
    and i.ORG_OU_CODE=#{orgOuCode}
    and i.ORG_OU_ID=#{orgOuId}

select t.VENDOR_ID, t.ORG_OU_ID, COUNT(t.PROJECT_ID) INQ_TIMES from (
select DISTINCT v.VENDOR_ID, i.ORG_OU_ID, p.PROJECT_ID from scc_sou_vendor v
join scc_sou_project p on p.PROJECT_ID = v.PROJECT_ID and p.SOU_TYPE='inq' and p.CREATE_APPROVAL_STATUS='APPROVED'
join scc_sou_item i on i.PROJECT_ID = p.PROJECT_ID

    and p.CREATION_DATE >= #{creationDateFrom}
    and p.CREATION_DATE < #{creationDateTo}

        and (v.VENDOR_ID, i.ORG_OU_ID) IN 
        (#{item.vendorId}, #{item.orgOuId})



) t GROUP BY t.VENDOR_ID, t.ORG_OU_ID

select t.VENDOR_ID, t.ORG_OU_ID, COUNT(t.PROJECT_ID) ORDER_TIMES from ( select DISTINCT v.VENDOR_ID, i.ORG_OU_ID, o.PROJECT_ID from scc_sou_vendor v join scc_sou_project p on p.PROJECT_ID = v.PROJECT_ID and p.SOU_TYPE='inq' and p.CREATE_APPROVAL_STATUS='APPROVED' join scc_sou_item i on i.PROJECT_ID = p.PROJECT_ID join scc_sou_order o on o.PROJECT_ID = p.PROJECT_ID and o.VENDOR_ID = v.VENDOR_ID and o.ORDER_STATUS='SUBMISSION'
and p.CREATION_DATE >= #{creationDateFrom} and p.CREATION_DATE < #{creationDateTo}
and (v.VENDOR_ID, i.ORG_OU_ID) IN (#{item.vendorId}, #{item.orgOuId})
) t GROUP BY t.VENDOR_ID, t.ORG_OU_ID

SELECT t.VENDOR_ID, t.ORG_OU_ID, COUNT(t.ITEM_ID) ITEM_TIMES from ( select DISTINCT v.VENDOR_ID, i.ORG_OU_ID, oi.PROJECT_ID, oi.ITEM_ID from scc_sou_vendor v join scc_sou_project p on p.PROJECT_ID = v.PROJECT_ID and p.SOU_TYPE='inq' and p.CREATE_APPROVAL_STATUS='APPROVED' join scc_sou_item i on i.PROJECT_ID = p.PROJECT_ID join scc_sou_order o on o.PROJECT_ID = p.PROJECT_ID and o.VENDOR_ID = v.VENDOR_ID and o.ORDER_STATUS='SUBMISSION' join scc_sou_order_item oi on oi.PROJECT_ID = o.PROJECT_ID and oi.ORDER_ID = o.ORDER_ID and oi.ORDER_STATUS='SUBMISSION' and i.SOU_ITEM_ID = oi.SOU_ITEM_ID
and p.CREATION_DATE >= #{creationDateFrom} and p.CREATION_DATE < #{creationDateTo}
and (v.VENDOR_ID, i.ORG_OU_ID) IN (#{item.vendorId}, #{item.orgOuId})
) t GROUP BY t.VENDOR_ID, t.ORG_OU_ID
